param([Parameter(Mandatory=$true)][string]$RouteFile, [string]$OutputLss = "Segment.lss")
$ids=@(); Get-Content $RouteFile | ForEach-Object { $line=($_ -split '#',2)[0].Trim(); if($line -and -not $line.StartsWith('@')){$ids+=$line} }
if($ids.Count -eq 0){throw 'No route targets found.'}
[xml]$xml='<Run version="1.7.0"><GameIcon/><GameName>Path of Exile 2</GameName><CategoryName>Ordered Segment</CategoryName><Metadata><Run id=""/><Platform usesEmulator="False">PC</Platform><Region/><Variables/></Metadata><Offset>00:00:00</Offset><AttemptCount>0</AttemptCount><Segments/></Run>'
foreach($id in $ids){$seg=$xml.CreateElement('Segment');$n=$xml.CreateElement('Name');$n.InnerText=$id;$seg.AppendChild($n)|Out-Null;$seg.AppendChild($xml.CreateElement('Icon'))|Out-Null;$st=$xml.CreateElement('SplitTimes');$s=$xml.CreateElement('SplitTime');$s.SetAttribute('name','Personal Best');$st.AppendChild($s)|Out-Null;$seg.AppendChild($st)|Out-Null;$seg.AppendChild($xml.CreateElement('BestSegmentTime'))|Out-Null;$seg.AppendChild($xml.CreateElement('SegmentHistory'))|Out-Null;$xml.Run.Segments.AppendChild($seg)|Out-Null};$xml.Save($OutputLss);Write-Host "Created $OutputLss with $($ids.Count) rows."
